<?php
declare(strict_types=1);
require_once __DIR__ . "/../../includes/seguridad.php";
exigirAdmin();
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$errores=[];$mensajes=[];
if(empty($_SESSION['csrf_unidades']))$_SESSION['csrf_unidades']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_unidades'];
$idMateria=filter_var($_GET['id_materia']??null,FILTER_VALIDATE_INT);if(!$idMateria||$idMateria<=0)$idMateria=null;
$grado=(string)($_GET['grado']??'');if(!in_array($grado,['9','10','11'],true))$grado='';
if(($_GET['creado']??'')==='1')$mensajes[]='Unidad temática creada correctamente.';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$errores[]='La sesión del formulario expiró. Recarga la página.';
 else if(($_POST['accion']??'')==='eliminar'){
  $uid=(int)($_POST['id_unidad']??0);try{$st=$conexion->prepare("SELECT es_predeterminada FROM unidades_tematicas WHERE id_unidad=?");$st->execute([$uid]);$u=$st->fetch(PDO::FETCH_ASSOC);if(!$u)$errores[]='La unidad no existe.';elseif((int)$u['es_predeterminada']===1)$errores[]='La Temática general de transición no se puede eliminar.';else{$st=$conexion->prepare("SELECT COUNT(*) FROM temas WHERE id_unidad=?");$st->execute([$uid]);$n=(int)$st->fetchColumn();if($n>0)$errores[]="No puedes eliminar esta unidad porque tiene {$n} tema(s) asociado(s).";else{$st=$conexion->prepare("DELETE FROM unidades_tematicas WHERE id_unidad=?");$st->execute([$uid]);$mensajes[]='Unidad temática eliminada correctamente.';}}}catch(PDOException $ex){$errores[]='No fue posible eliminar la unidad temática.';}
 }
}
try{$materias=$conexion->query("SELECT id_materia,nombre FROM materias ORDER BY nombre")->fetchAll(PDO::FETCH_ASSOC);$sql="SELECT u.id_unidad,u.id_materia,u.grado,u.nombre,u.descripcion,u.estado,u.es_predeterminada,m.nombre AS materia,COUNT(t.id_tema) AS total_temas FROM unidades_tematicas u INNER JOIN materias m ON m.id_materia=u.id_materia LEFT JOIN temas t ON t.id_unidad=u.id_unidad WHERE u.estado='Activa'";$p=[];if($idMateria){$sql.=" AND u.id_materia=?";$p[]=$idMateria;}if($grado){$sql.=" AND u.grado=?";$p[]=$grado;}$sql.=" GROUP BY u.id_unidad,m.nombre ORDER BY m.nombre,CAST(u.grado AS UNSIGNED),u.es_predeterminada DESC,u.nombre";$st=$conexion->prepare($sql);$st->execute($p);$unidades=$st->fetchAll(PDO::FETCH_ASSOC);}catch(PDOException $ex){$materias=[];$unidades=[];$errores[]='No fue posible cargar las unidades temáticas.';}
$urlDashboard=urlAplicacion('/admin/dashboard.php');$urlNuevo=urlAplicacion('/admin/contenidos/nueva_unidad.php');$urlMaterias=urlAplicacion('/admin/contenidos/materias.php');$urlSalir=urlAplicacion('/cerrar_sesion.php');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unidades temáticas | Studia360</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="<?=e(urlAplicacion('/admin/assets/studia-admin.css'))?>"><style>.unit-card{height:100%;padding:20px;background:#fff;border:1px solid #e4eaf2;border-radius:20px;box-shadow:0 10px 28px rgba(23,32,51,.045);display:flex;flex-direction:column}.unit-icon{width:46px;height:46px;border-radius:14px;background:#eff6ff;color:#2563eb;display:grid;place-items:center;font-size:1.15rem}.unit-actions{margin-top:auto;display:flex;gap:8px}.unit-actions .btn{border-radius:10px;font-weight:700}.filterbar{background:#fff;border:1px solid #e4eaf2;border-radius:20px;padding:16px;box-shadow:0 8px 24px rgba(23,32,51,.04)}.chip{border:1px solid #dbe3ee;background:#fff;color:#526176;border-radius:11px;padding:.5rem .75rem;text-decoration:none;font-weight:750;font-size:.8rem}.chip.active{background:#2563eb;color:#fff;border-color:#2563eb}</style></head><body class="s360-admin s360-content-theme"><nav class="s360-topbar"><div class="container-fluid px-3 px-lg-4 py-2 d-flex justify-content-between align-items-center"><a class="s360-brand d-flex align-items-center gap-2" href="<?=e($urlDashboard)?>"><span class="s360-brand-icon"><i class="bi bi-mortarboard-fill"></i></span>Studia360 <span class="badge text-bg-primary">Admin</span></a><div class="d-flex gap-2"><a class="btn btn-light border" href="<?=e($urlMaterias)?>"><i class="bi bi-book me-1"></i>Materias</a><a class="btn btn-outline-secondary" href="<?=e($urlSalir)?>">Salir</a></div></div></nav><main class="s360-shell"><section class="s360-hero mb-4"><div class="row align-items-center g-3"><div class="col"><div class="s360-kicker">Estructura académica</div><h1 class="h2 mb-2">Unidades temáticas</h1><p class="mb-0 opacity-75">Cada unidad pertenece a una materia y a un grado específico.</p></div><div class="col-auto"><a class="btn btn-light s360-btn" href="<?=e($urlNuevo)?>"><i class="bi bi-plus-lg me-1"></i>Nueva unidad</a></div></div></section><?php foreach($mensajes as $m):?><div class="alert alert-success border-0 shadow-sm"><?=e($m)?></div><?php endforeach;?><?php foreach($errores as $er):?><div class="alert alert-danger border-0 shadow-sm"><?=e($er)?></div><?php endforeach;?><section class="filterbar mb-4"><form id="filtroUnidades" method="get" class="row g-3 align-items-end"><div class="col-12 col-md-5"><label class="form-label small fw-bold">Materia</label><select class="form-select" name="id_materia"><option value="">Todas las materias</option><?php foreach($materias as $m):?><option value="<?=$m['id_materia']?>" <?=((int)$idMateria===(int)$m['id_materia'])?'selected':''?>><?=e($m['nombre'])?></option><?php endforeach;?></select></div><div class="col-12 col-md-4"><label class="form-label small fw-bold">Grado</label><div class="d-flex gap-2 flex-wrap"><?php foreach([''=>'Todos','9'=>'9°','10'=>'10°','11'=>'11°'] as $g=>$label):?><a class="chip <?=$grado===$g?'active':''?>" href="?<?=http_build_query(array_filter(['id_materia'=>$idMateria,'grado'=>$g],fn($v)=>$v!==null&&$v!==''))?>"><?=$label?></a><?php endforeach;?></div></div></form></section><div class="row g-3"><?php if(!$unidades):?><div class="col-12"><div class="s360-empty text-center p-5"><div class="s360-iconbox mx-auto mb-3"><i class="bi bi-collection"></i></div><h2 class="h5 fw-bold">No hay unidades temáticas</h2><p class="s360-muted mb-0">Crea una unidad para comenzar a organizar los temas.</p></div></div><?php endif;?><?php foreach($unidades as $u):?><div class="col-12 col-md-6 col-xl-4"><article class="unit-card"><div class="d-flex gap-3 align-items-start mb-3"><div class="unit-icon"><i class="bi bi-collection-fill"></i></div><div class="min-w-0"><div class="d-flex gap-2 flex-wrap"><span class="badge rounded-pill text-bg-primary"><?=e($u['grado'])?>°</span><?php if((int)$u['es_predeterminada']===1):?><span class="badge rounded-pill text-bg-secondary">Transición</span><?php endif;?></div><h2 class="h5 fw-bold mt-2 mb-1"><?=e($u['nombre'])?></h2><div class="small text-secondary"><?=e($u['materia'])?></div></div></div><p class="small text-secondary mb-3" style="line-height:1.55"><?=e($u['descripcion']?:'Sin descripción.')?></p><div class="mb-3"><span class="badge rounded-pill bg-light text-dark border"><?=((int)$u['total_temas'])?> <?=((int)$u['total_temas']===1?'tema':'temas')?></span></div><div class="unit-actions"><a class="btn btn-primary flex-grow-1" href="temas.php?id_materia=<?=(int)$u['id_materia']?>&id_unidad=<?=(int)$u['id_unidad']?>"><i class="bi bi-journal-text me-1"></i>Ver temas</a><a class="btn btn-outline-secondary" href="editar_unidad.php?id=<?=(int)$u['id_unidad']?>" title="Editar unidad"><i class="bi bi-pencil"></i></a><?php if((int)$u['es_predeterminada']===0):?><form method="post" class="d-inline" onsubmit="return confirm('¿Eliminar esta unidad temática?');"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="accion" value="eliminar"><input type="hidden" name="id_unidad" value="<?=$u['id_unidad']?>"><button class="btn btn-outline-danger" type="submit" title="Eliminar"><i class="bi bi-trash3"></i></button></form><?php endif;?></div></article></div><?php endforeach;?></div></main><script>document.querySelector('#filtroUnidades select[name="id_materia"]')?.addEventListener('change',function(){document.getElementById('filtroUnidades').submit()});</script></body></html>
